141	    @Test
142	    void taskHttpErrors() throws Exception {
143	        report("INC-510");
144	        takeover("INC-510", "alice");
145	
146	        // 缺少 X-Actor-Id → 400
147	        mvc.perform(post("/api/incidents/{k}/tasks", "INC-510")
148	                        .contentType(MediaType.APPLICATION_JSON)
149	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"T-1\","
150	                                + "\"groupCode\":\"G\",\"title\":\"t\"}"))
151	                .andExpect(status().isBadRequest());
152	        // groupCode 为空 → 400
153	        mvc.perform(post("/api/incidents/{k}/tasks", "INC-510")
154	                        .header("X-Actor-Id", "alice")
155	                        .contentType(MediaType.APPLICATION_JSON)
156	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"T-1\","
157	                                + "\"groupCode\":\" \",\"title\":\"t\"}"))
158	                .andExpect(status().isBadRequest())
159	                .andExpect(jsonPath("$.code").value("BAD_REQUEST"));
160	        // 非当前指挥人 → 409
161	        mvc.perform(post("/api/incidents/{k}/tasks", "INC-510")
162	                        .header("X-Actor-Id", "bob")
163	                        .contentType(MediaType.APPLICATION_JSON)
164	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"T-1\","
165	                                + "\"groupCode\":\"G\",\"title\":\"t\"}"))
166	                .andExpect(status().isConflict());
167	        // 事件不存在 → 404
168	        mvc.perform(post("/api/incidents/{k}/tasks", "INC-404")
169	                        .header("X-Actor-Id", "alice")
170	                        .contentType(MediaType.APPLICATION_JSON)
171	                        .content("{\"commandKey\":\"" + key() + "\",\"taskKey\":\"T-1\","
172	                                + "\"groupCode\":\"G\",\"title\":\"t\"}"))
173	                .andExpect(status().isNotFound());
174	        mvc.perform(get("/api/incidents/{k}/tasks", "INC-404"))
175	                .andExpect(status().isNotFound());
