181	    @Test
182	    void taskHttpCycleAndResolveGate() throws Exception {
183	        report("INC-520");
184	        report("INC-521");
185	        takeover("INC-520", "alice");
186	        takeover("INC-521", "bob");
187	        createTask("INC-520", "alice", "T-1", "[\"INC-521\"]");
