    EXECUTING,

    /** 阻断：执行前检查发现凭据已过期或已撤销；只能凭有效新凭据再派发。 */
    BLOCKED,

    /** 已完成：EXECUTING 任务经执行前检查通过后完成，或未派发的 OPEN 任务直接完成。 */
    DONE,

    /** 已取消。 */
    CANCELLED;
}

