            blockers, task.createdBy(), task.createdAt(), task.doneBy(), task.doneAt(),
            task.cancelledBy(), task.cancelledAt(), credential,
            task.blockReason() == null ? null : task.blockReason().name(), task.blockedAt(),
            dispatchViews);
}

